from pathlib import Path


class DiskScoreStore:
    def __init__(self, root: Path) -> None:
        self._root = root

    def read(self, catalogue_number: str) -> bytes:
        return (self._root / f"{catalogue_number}.pdf").read_bytes()


def lend_score(store: DiskScoreStore, catalogue_number: str) -> bytes:
    return store.read(catalogue_number)

